@EventBusSubscriber(modid=ModularMagic.MOD_ID,value=Dist.CLIENT)
public final class ArtificeClientSmoke {
    private static int ticks,stage,changed;private static String armed="";private static boolean savedPause;
    private static final BlockPos POS=new BlockPos(16,100,16);
    @SubscribeEvent public static void tick(ClientTickEvent.Post event){
        if(!Boolean.getBoolean("modularmagic.artificeSmoke"))return;var mc=Minecraft.getInstance();
        if(++ticks>3000){ModularMagic.LOGGER.error("ARTIFICE_SMOKE_TIMEOUT stage={}",stage);mc.stop();return;}
        if(mc.player==null||mc.getSingleplayerServer()==null||ticks-changed<20)return;
        try{switch(stage){
            case 0->{savedPause=mc.options.pauseOnLostFocus;mc.options.pauseOnLostFocus=false;mc.player.getInventory().selected=0;mc.options.guiScale().set(2);mc.resizeDisplay();server(mc,()->{var p=player(mc);p.setGameMode(GameType.SURVIVAL);p.setInvulnerable(true);p.setHealth(p.getMaxHealth());p.fallDistance=0;for(int x=12;x<=20;x++)for(int z=12;z<=20;z++)p.serverLevel().setBlockAndUpdate(new BlockPos(x,99,z),Blocks.SMOOTH_STONE.defaultBlockState());p.teleportTo(16.5,101,18.5);p.getInventory().clearContent();p.getInventory().selected=0;p.setData(ResearchKnowledge.DATA,new CompoundTag());ResearchCatalog.get("K00").nodes().forEach(n->ResearchKnowledge.learn(p,n));p.serverLevel().setBlockAndUpdate(POS,ResearchContent.TABLE.get().defaultBlockState());});next();}
            case 1->{useBlock(mc);next();}
            case 2->{require(!(mc.screen instanceof ResearchScreen),"Empty hands opened research");server(mc,()->{player(mc).setItemInHand(InteractionHand.MAIN_HAND,ResearchContent.INK.toStack());});next();}
            case 3->{
                if(armed.isEmpty()&&mc.player.getMainHandItem().is(ResearchContent.INK.get())){useBlock(mc);armed="ink";changed=ticks;return;}
                if(armed.equals("ink")){server(mc,()->{var p=player(mc);var table=(RuneTableBlockEntity)p.level().getBlockEntity(POS);require(table.inventory.getItem(1).is(ResearchContent.INK.get())&&p.getMainHandItem().isEmpty(),"Held ink was not placed on the research desk");p.setItemInHand(InteractionHand.MAIN_HAND,ResearchNoteItem.create("K01",false));});armed="notes";changed=ticks;return;}
                if(!(mc.player.getMainHandItem().getItem() instanceof ResearchNoteItem))return;useBlock(mc);armed="";next();
            }
            case 4->{if(!(mc.screen instanceof ResearchScreen)||!(mc.player.containerMenu instanceof ResearchMenu m)||m.document==null)return;require(m.slots.get(0).isActive()&&!m.slots.get(0).mayPickup(mc.player)&&m.slots.get(1).isActive()&&m.slots.subList(10,m.slots.size()).stream().allMatch(s->s.isActive()),"Research must show backpack slots alongside paper and ink");if(armed.isEmpty()){mc.gameMode.handleInventoryMouseClick(m.containerId,1,0,ClickType.PICKUP,mc.player);mc.gameMode.handleInventoryMouseClick(m.containerId,38,0,ClickType.PICKUP,mc.player);armed="pack";changed=ticks;return;}if(armed.equals("pack")){require(m.supplies.getItem(1).isEmpty()&&mc.player.getInventory().getItem(1).is(ResearchContent.INK.get()),"Ink could not be moved into the visible backpack");shift(mc,m,38);armed="desk";changed=ticks;return;}if(!m.supplies.getItem(1).is(ResearchContent.INK.get()))return;armed="";click(mc,80,height(mc)-16,0);next();}
            case 5->{if(!(mc.player.containerMenu instanceof ResearchMenu m)||!m.paid)return;require(m.supplies.getItem(1).getDamageValue()==m.inkCost,"Research did not spend its desk ink");insertTrigger(mc,m);next();}
            case 6->{if(!(mc.player.containerMenu instanceof ResearchMenu m)||m.document.nodes().size()!=2)return;screenshot(mc,"artifice-research.png");mc.player.closeContainer();next();}
            case 7->{server(mc,()->{var p=player(mc);require(p.getInventory().items.stream().anyMatch(s->s.is(ResearchContent.NOTE.get())),"Research did not return its notes");require(ResearchKnowledge.state(p).getString("draft:effect/push").isEmpty()&&ResearchKnowledge.state(p).getString("paid:effect/push").isEmpty(),"Research kept unfinished progress");p.getInventory().clearContent();ResearchCatalog.all().forEach(t->{t.nodes().forEach(n->ResearchKnowledge.learn(p,n));ResearchKnowledge.learn(p,t.id());});p.serverLevel().setBlockAndUpdate(POS,ResearchContent.CARVER.get().defaultBlockState());p.setItemInHand(InteractionHand.MAIN_HAND,ArtificeContent.BLANK_CORE.toStack());p.getInventory().setItem(1,ResearchContent.BLANK.toStack());p.getInventory().setItem(2,new ItemStack(Items.CLAY_BALL,2));});next();}
            case 8->{useBlock(mc);next();}
            case 9->{if(!(mc.screen instanceof CarvingScreen)||!(mc.player.containerMenu instanceof ResearchMenu m))return;require(m.palette.isEmpty(),"An empty carving desk listed recipes");shift(mc,m,37);next();}
            case 10->{if(!(mc.player.containerMenu instanceof ResearchMenu m)||m.palette.size()!=3)return;if(!armed.equals("root/instant")){chooseCarving(mc,m,"root/instant");armed="root/instant";changed=ticks;return;}click(mc,211,135,0);armed="";next();}
            case 11->{if(!(mc.player.containerMenu instanceof ResearchMenu m)||m.supplies.getItem(9).isEmpty())return;require(m.supplies.getItem(9).is(cn.nulladev.modularmagic.registry.ModContent.NODES.get("root/instant").get()),"The core carving made the wrong item");shift(mc,m,9);next();}
            case 12->{if(!(mc.player.containerMenu instanceof ResearchMenu m)||!m.supplies.getItem(9).isEmpty())return;require(m.palette.isEmpty(),"The list did not clear after consuming the blank core");shift(mc,m,39);next();}
            case 13->{if(!(mc.player.containerMenu instanceof ResearchMenu m)||m.palette.size()!=ArtificeContent.PLATES.size())return;if(!armed.equals("plate:K32")){chooseCarving(mc,m,"plate:K32");armed="plate:K32";changed=ticks;return;}click(mc,211,135,0);armed="";next();}
            case 14->{if(!(mc.player.containerMenu instanceof ResearchMenu m)||!m.supplies.getItem(9).is(ArtificeContent.PLATES.get("K32").get()))return;screenshot(mc,"artifice-carving.png");server(mc,()->{var p=player(mc);p.closeContainer();p.serverLevel().setBlockAndUpdate(POS,EnergyContent.BLOCKS.get(EnergyContent.Kind.ENCHANTER).get().defaultBlockState());p.getInventory().clearContent();var be=(EnergyBlockEntity)p.level().getBlockEntity(POS);be.energy=1000000*cn.nulladev.modularmagic.mana.ManaStorage.SCALE;var sharp=p.level().registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(Enchantments.SHARPNESS);be.enchantInventory.setItem(0,enchanted(Items.DIAMOND_SWORD,sharp,1));be.enchantInventory.setItem(1,enchanted(Items.ENCHANTED_BOOK,sharp,2));be.changed();});next();}
            case 15->{useBlock(mc);next();}
            case 16->{if(!(mc.screen instanceof EnchantingScreen)||!(mc.player.containerMenu instanceof EnchantingMenu))return;click(mc,24,78,0);next();}
            case 17->{if(!(mc.player.containerMenu instanceof EnchantingMenu m)||m.selected!=1||!m.possible)return;require(m.cost==6000,"The additive quote did not follow the anvil cost");click(mc,140,33,0);next();}
            case 18->{if(!(mc.player.containerMenu instanceof EnchantingMenu m))return;var sharp=mc.level.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(Enchantments.SHARPNESS);if(AetherEnchanting.enchantments(m.slots.get(0).getItem()).getLevel(sharp)!=3)return;require(m.slots.get(1).getItem().is(Items.ENCHANTED_BOOK)&&m.energy==994000,"Enchantment consumed its sample or the wrong aether amount");screenshot(mc,"artifice-enchanter.png");mc.player.closeContainer();next();}
            case 19->{var runtime=ArtificeJeiPlugin.runtime;if(runtime==null)return;var manager=runtime.getRecipeManager();long carvings=manager.createRecipeLookup(ArtificeJeiPlugin.CARVING).get().count(),sigils=manager.createRecipeLookup(ArtificeJeiPlugin.SIGIL).get().count(),enchantments=manager.createRecipeLookup(ArtificeJeiPlugin.ENCHANTING).get().count();require(carvings==100+ArtificeContent.PLATES.size()&&sigils==20&&enchantments>20,"JEI omitted custom recipes: "+carvings+","+sigils+","+enchantments);require(manager.createRecipeLookup(ArtificeJeiPlugin.CONDENSING).get().count()==3&&manager.createRecipeLookup(ArtificeJeiPlugin.ASSEMBLY).get().count()==4,"JEI omitted condensation or spell assembly");require(manager.createRecipeLookup(ArtificeJeiPlugin.BINDING).get().count()>=50,"JEI omitted reversible gravity bindings");for(var family:MimicFamily.values())require(manager.createRecipeLookup(ArtificeJeiPlugin.BINDING).get().anyMatch(r->r.family()==family),"Missing JEI binding family "+family);var craft=manager.createRecipeLookup(mezz.jei.api.constants.RecipeTypes.CRAFTING).get().map(h->h.id().toString()).collect(java.util.stream.Collectors.toSet());for(String id:cn.nulladev.modularmagic.generator.GeneratorCatalog.RULES.keySet())require(craft.contains("modularmagic:generator_"+id),"JEI omitted generator "+id);require(craft.contains("modularmagic:generator_housing"),"JEI omitted the custom housing recipe");require(craft.contains("modularmagic:mana_container_expanded"),"JEI omitted the state-preserving container upgrade");ModularMagic.LOGGER.info("ARTIFICE_JEI_VERIFIED carvings={} sigils={} enchantments={}",carvings,sigils,enchantments);runtime.getRecipesGui().showTypes(List.of(ArtificeJeiPlugin.CARVING));next();}
            case 20->{screenshot(mc,"artifice-jei-carving.png");ArtificeJeiPlugin.runtime.getRecipesGui().showTypes(List.of(ArtificeJeiPlugin.SIGIL));next();}
            case 21->{screenshot(mc,"artifice-jei-sigils.png");ArtificeJeiPlugin.runtime.getRecipesGui().showTypes(List.of(ArtificeJeiPlugin.ENCHANTING));next();}
            case 22->{screenshot(mc,"artifice-jei-enchanting.png");var registry=Class.forName("vazkii.patchouli.common.book.BookRegistry");var books=(Map<?,?>)registry.getField("books").get(registry.getField("INSTANCE").get(null));var book=books.get(ModularMagic.id("assembly_guide"));var contents=book.getClass().getMethod("getContents").invoke(book);require(!(boolean)contents.getClass().getMethod("isErrored").invoke(contents),"The guide failed to load");var chapters=(Map<?,?>)contents.getClass().getField("entries").get(contents);var categories=(Map<?,?>)contents.getClass().getField("categories").get(contents);require(categories.size()==7,"Handbook categories were not reorganized");var merged=chapters.get(ModularMagic.id("equipment/unformed"));require(merged!=null,"Missing shared dark matter chapter");for(String part:ArtificeContent.GEAR.keySet()){require(!chapters.containsKey(ModularMagic.id("equipment/unformed_"+part)),"Equipment still has a redundant chapter "+part);var mapping=contents.getClass().getMethod("getEntryForStack",ItemStack.class).invoke(contents,ArtificeContent.GEAR.get(part).toStack());require(mapping!=null,"Gear lost its handbook lookup "+part);var mapped=mapping.getClass().getMethod("getFirst").invoke(mapping);require(mapped.getClass().getMethod("getId").invoke(mapped).equals(ModularMagic.id("equipment/unformed")),"Gear lookup did not use the shared chapter "+part);}for(String id:List.of("water","lava","cobblestone","stone","basalt","snow","ice","fire","rails","plants","carpets","tnt","gravity","powder_snow","obsidian","amethyst_cluster","pointed_dripstone","sculk"))require(chapters.containsKey(ModularMagic.id("mimics/"+id)),"Missing mimic chapter "+id);require(!chapters.containsKey(ModularMagic.id("mimics/sand"))&&!chapters.containsKey(ModularMagic.id("mimics/gravel")),"Gravity materials must share one chapter");var client=Class.forName("vazkii.patchouli.client.book.ClientBookRegistry");client.getMethod("displayBookGui",net.minecraft.resources.ResourceLocation.class,net.minecraft.resources.ResourceLocation.class,int.class).invoke(client.getField("INSTANCE").get(null),ModularMagic.id("assembly_guide"),ModularMagic.id("energy/enchanting"),0);next();}
            case 23->{screenshot(mc,"artifice-enchanting-guide.png");for(var item:ArtificeContent.GEAR.values())require(!mc.getItemRenderer().getModel(item.toStack(),mc.level,mc.player,0).getParticleIcon().contents().name().getPath().equals("missingno"),"Missing gear texture "+item.getId());var distinct=java.util.Collections.newSetFromMap(new java.util.IdentityHashMap<net.minecraft.client.resources.model.BakedModel,Boolean>());for(String material:List.of("water","lava","cobblestone","stone","basalt","snow","ice","fire","rail","powered_rail","detector_rail","activator_rail","tnt","sand","red_sand","gravel","anvil","dragon_egg","red_concrete_powder")){var stack=PlaceholderItem.create(net.minecraft.resources.ResourceLocation.withDefaultNamespace(material));var model=mc.getItemRenderer().getModel(stack,mc.level,mc.player,0);require(model!=mc.getModelManager().getMissingModel(),"Missing mimic model "+material);require(distinct.add(model),"Mimics reused the same model: "+material);}showChapter("energy/generator_snow",0);next();}
            case 24->{screenshot(mc,"handbook-snow-generator.png");showChapter("mimics/water",0);next();}
            case 25->{screenshot(mc,"handbook-water-mimic.png");showChapter("mimics/gravity",2);next();}
            case 26->{screenshot(mc,"handbook-gravity-mimic.png");showChapter("equipment/unformed",4);next();}
            case 27->{screenshot(mc,"handbook-unformed-equipment.png");ModularMagic.LOGGER.info("MODULARMAGIC_ARTIFICE_SMOKE_PASSED");mc.options.pauseOnLostFocus=savedPause;stage=99;mc.stop();}
        }}catch(Throwable ex){ModularMagic.LOGGER.error("ARTIFICE_SMOKE_FAILED stage="+stage,ex);stage=99;mc.stop();}
    }
    private static void showChapter(String entry,int page)throws ReflectiveOperationException{var client=Class.forName("vazkii.patchouli.client.book.ClientBookRegistry");client.getMethod("displayBookGui",net.minecraft.resources.ResourceLocation.class,net.minecraft.resources.ResourceLocation.class,int.class).invoke(client.getField("INSTANCE").get(null),ModularMagic.id("assembly_guide"),ModularMagic.id(entry),page);}
    private static ItemStack enchanted(Item item,Holder<Enchantment> e,int level){var stack=new ItemStack(item);var v=new ItemEnchantments.Mutable(ItemEnchantments.EMPTY);v.set(e,level);stack.set(item==Items.ENCHANTED_BOOK?DataComponents.STORED_ENCHANTMENTS:DataComponents.ENCHANTMENTS,v.toImmutable());return stack;}
    private static net.minecraft.server.level.ServerPlayer player(Minecraft mc){return mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());}
    private static void server(Minecraft mc,Runnable action){mc.getSingleplayerServer().execute(()->{try{action.run();}catch(Throwable t){ModularMagic.LOGGER.error("ARTIFICE_SMOKE_SERVER_FAILED stage="+stage,t);stage=99;mc.execute(mc::stop);}});}
    private static void require(boolean condition,String message){if(!condition)throw new IllegalStateException(message);}
    private static void next(){ModularMagic.LOGGER.info("ARTIFICE_SMOKE_STAGE {}",stage);stage++;changed=ticks;}
    private static void useBlock(Minecraft mc){mc.gameMode.useItemOn(mc.player,InteractionHand.MAIN_HAND,new BlockHitResult(POS.getCenter().add(0,.5,0),Direction.UP,POS,false));}
    private static int width(Minecraft mc){return mc.screen instanceof CarvingScreen?244:mc.screen instanceof EnchantingScreen?194:Math.min(mc.getWindow().getGuiScaledWidth()-16,620);}
    private static int height(Minecraft mc){return mc.screen instanceof CarvingScreen||mc.screen instanceof EnchantingScreen?232:Math.min(mc.getWindow().getGuiScaledHeight()-16,400);}
    private static void click(Minecraft mc,int x,int y,int button){mc.screen.mouseClicked((mc.getWindow().getGuiScaledWidth()-width(mc))/2+x,(mc.getWindow().getGuiScaledHeight()-height(mc))/2+y,button);}
    private static void shift(Minecraft mc,ResearchMenu m,int slot){mc.gameMode.handleInventoryMouseClick(m.containerId,slot,0,ClickType.QUICK_MOVE,mc.player);}
    private static void chooseCarving(Minecraft mc,ResearchMenu m,String key){int index=new ArrayList<>(m.palette.keySet()).indexOf(key),scroll=Math.max(0,index/7-4);require(index>=0,"Carving missing "+key);if(scroll>0)mc.screen.mouseScrolled((mc.getWindow().getGuiScaledWidth()-244)/2+40,(mc.getWindow().getGuiScaledHeight()-232)/2+70,0,-scroll);click(mc,9+index%7*24+10,27+(index/7-scroll)*24+10,0);}
    private static void insertTrigger(Minecraft mc,ResearchMenu m){int index=new ArrayList<>(m.palette.keySet()).indexOf("trigger/self_pos");click(mc,width(mc)-178+index%7*24+10,57+index/7*24+10,0);var rows=new ArrayList<String>();flatten(m.document.root,rows);click(mc,80,53+rows.indexOf("root/instant:trigger_type")*21+10,0);}
    private static void flatten(SpellDocument.Node n,List<String> rows){rows.add(n.template);for(var s:n.schema().slots()){n.children.get(s.key()).forEach(c->flatten(c,rows));if(n.children.get(s.key()).isEmpty()||s.list())rows.add(n.template+":"+s.key());}}
    private static void screenshot(Minecraft mc,String name){Screenshot.grab(mc.gameDirectory,name,mc.getMainRenderTarget(),c->ModularMagic.LOGGER.info("ARTIFICE_SCREENSHOT {}",name));}
}
